history = []
def add_turn(role, content):
    history.append({"role": role, "content": content})
    if len(history) > MAX_TURNS_KEPT_IN_FULL:
        history.pop(0)  # oldest turn dropped, or summarized instead

persisted_resources = {}
def read_resource_cached(uri):
    if uri not in persisted_resources:
        persisted_resources[uri] = server.read_resource(uri)
    return persisted_resources[uri]  # reused across turns, may go stale

def should_persist(item):
    return (
        item.referenced_more_than_once
        or item.slow_changing
        or item.reused_by_multiple_tool_calls
    )

class SessionState:
    def __init__(self):
        self.persisted_resources = {}
        self.persisted_facts = []
        self.history = []
    # all of this lives in process memory unless explicitly backed by storage

def get_persisted(uri):
    entry = persisted_resources.get(uri)
    if entry and time.time() - entry["captured_at"] < MAX_AGE_SECONDS:
        return entry["content"]
    return None  # caller should refresh from the server

def rehydrate_if_needed(summary_entry, current_question):
    if is_relevant(summary_entry.topic, current_question):
        return server.read_resource(summary_entry.uri)  # full content, on demand
    return summary_entry.summary  # cheap, always-available fallback

class PersistenceStrategy:
    def decide(self, item):
        if item.explicitly_referenced_again:
            return "persist_full"
        if item.slow_changing:
            return "persist_summary"
        return "discard"
